import React, { useState, useEffect } from "react";

const Test = () => {
    const [topic, setTopic] = useState("");
    const [topics, setTopics] = useState([]); // Store previous topics
    const [questions, setQuestions] = useState([]);
    const [answers, setAnswers] = useState({}); // Store selected answers
    const [loading, setLoading] = useState(false);

    // Load previous topics from localStorage
    useEffect(() => {
        const savedTopics = JSON.parse(localStorage.getItem("chatTopics")) || [];
        setTopics(savedTopics);
    }, []);

    const fetchAIQuestions = async () => {
        if (!topic) return;
        setLoading(true);
        setQuestions([]);
        setAnswers({}); // Reset answers when generating new questions

        try {
            const response = await fetch("http://localhost:5000/generate-questions", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ topic, numQuestions: 10 }), // Request more questions
            });

            const data = await response.json();
            if (data.questions && data.questions.length > 0) {
                setQuestions(data.questions);
            }
        } catch (error) {
            console.error("Error fetching AI questions:", error);
        } finally {
            setLoading(false);
        }
    };

    // Handle answer selection
    const handleAnswerSelect = (questionIndex, selectedOption) => {
        setAnswers((prevAnswers) => ({
            ...prevAnswers,
            [questionIndex]: selectedOption,
        }));
    };

    return (
        <div style={{ padding: "20px", backgroundColor: "#fff", color: "#000" }}>
            <h2>Generate AI Questions</h2>

            {/* Dropdown for selecting previous topics */}
            <select value={topic} onChange={(e) => setTopic(e.target.value)} style={{ marginRight: "10px" }}>
                <option value="">Select a Topic</option>
                {topics.length > 0 ? (
                    topics.map((t, index) => <option key={index} value={t}>{t}</option>)
                ) : (
                    <option disabled>No topics found</option>
                )}
            </select>

            <button onClick={fetchAIQuestions} disabled={loading || !topic}>
                {loading ? "Generating..." : "Generate Questions"}
            </button>

            {questions.length > 0 && (
                <div>
                    <h3>Generated Questions</h3>
                    {questions.map((q, index) => (
                        <div key={index} style={{ marginBottom: "15px", borderBottom: "1px solid #ccc", paddingBottom: "10px" }}>
                            <strong>{index + 1}. {q.question}</strong>
                            <div>
                                {Object.entries(q.options).map(([key, option]) => (
                                    <div key={key}>
                                        <input
                                            type="radio"
                                            name={`question-${index}`}
                                            value={key}
                                            checked={answers[index] === key}
                                            onChange={() => handleAnswerSelect(index, key)}
                                        />
                                        <label style={{ marginLeft: "5px" }}>{option}</label>
                                    </div>
                                ))}
                            </div>
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
};

export default Test;
